"""Rebuilds assets/icons-lib.js: the icons people can put on a slide (Lucide, ISC). Usage: python3 tools/build_icon_library.py <savcomponents>/icons/<version>"""
import sys, os, re, json
src = sys.argv[1]
root = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')
al = json.load(open(src + '/aliases.json'))
names = '''activity alarm-clock anchor apple archive armchair arrow-big-right arrow-down arrow-left arrow-right arrow-up atom award baby backpack badge-check banana banknote battery-full bean beer bell bike binary bird bluetooth boat bone book book-open bookmark bot box brain briefcase brush bug building building-2 bus cake calculator calendar calendar-check camera car carrot castle cat chart-bar chart-line chart-pie check chef-hat cherry circle circle-check circle-question-mark circle-x clapperboard clipboard-list clock cloud cloud-rain cloud-sun clover code coffee cog coins compass computer cookie cpu credit-card croissant crown database diamond dice-5 dna dog dollar-sign door-open download droplet drum dumbbell ear earth egg euro eye factory feather film fingerprint fire-extinguisher fish flag flame flask-conical flower flower-2 folder footprints frown fuel gamepad-2 gauge gem ghost gift glasses globe graduation-cap grape guitar hammer hand hand-heart handshake hard-drive hash headphones heart heart-pulse hexagon hospital hourglass house ice-cream-cone image inbox infinity info key keyboard lamp landmark languages laptop layers leaf library lightbulb link list-checks lock luggage magnet mail map map-pin medal megaphone meh message-circle messages-square mic microscope milestone minus monitor moon mountain mouse-pointer-2 move-right music navigation newspaper notebook-pen octagon-alert package paintbrush palette paperclip party-popper paw-print pen pencil percent phone piggy-bank pin pizza plane plant plug plus power presentation printer puzzle quote rabbit radio rainbow receipt recycle refresh-cw ribbon rocket route ruler sailboat salad save scale school scissors search send server settings share-2 shield shield-check ship shirt shopping-bag shopping-cart shovel smartphone smile snail snowflake sofa sparkles speaker sprout square squirrel stamp star stethoscope store sun sunrise sword syringe tablet tag target telescope tent test-tube thermometer thumbs-down thumbs-up ticket timer tractor train-front trash tree-palm tree-pine trending-down trending-up triangle triangle-alert trophy truck tv umbrella university user user-check users utensils vault video volleyball vote wallet wand-sparkles watch waves wheat wifi wind wine wrench x zap'''.split()
out = {}
for n in names:
    f = f'{src}/{al.get(n, n)}.svg'
    if not os.path.exists(f):
        continue
    m = re.search(r'<svg[^>]*>(.*)</svg>', open(f).read(), re.S)
    out[n] = re.sub(r'\s+', ' ', m.group(1)).strip().replace('> <', '><').replace(' />', '/>')
open(root + '/assets/icons-lib.js', 'w').write('/** Icons for the slides: Lucide (ISC, see icons/LICENSE-lucide.txt). Made by tools/build_icon_library.py. */\nexport const ICON_PATHS = ' + json.dumps(out, separators=(',', ':')) + ';\n')
print(len(out), 'icons', len(names) - len(out), 'missing', os.path.getsize(root + '/assets/icons-lib.js') // 1024, 'KB')
